def mapa_colunas_df(df):
    return {
        str(col).strip().lower(): col
        for col in df.columns
    }


def serie_texto(df, coluna):
    if not coluna or coluna not in df.columns:
        return pd.Series(dtype="object")

    return (
        df[coluna]
        .fillna("")
        .astype(str)
        .str.strip()
    )


def valores_unicos(df, coluna):
    valores = serie_texto(df, coluna)
    valores = valores[valores != ""]

    return sorted(
        valores.unique().tolist(),
        key=lambda valor: valor.lower(),
    )


def contar_unicos(df, coluna):
    valores = serie_texto(df, coluna)
    valores = valores[valores != ""]

    if valores.empty:
        return 0

    return int(
        valores.str.lower().nunique()
    )


def localizar_colunas(df):
    mapa = mapa_colunas_df(df)

    return {
        "protocolo": mapa.get("número do protocolo"),
        "nome": mapa.get("nome completo"),
        "status": mapa.get("status do atendimento"),
        "criado": mapa.get("criado em"),
        "atualizado": mapa.get("atualizado em"),
        "unidade": (
            mapa.get("atendido em")
            or mapa.get("unidade / osc")
            or mapa.get("unidade/osc")
            or mapa.get("nome da unidade")
            or mapa.get("nome da osc")
        ),
        "usuario": mapa.get("atendido por"),
    }


def converter_datas(serie):
    if pd.api.types.is_datetime64_any_dtype(serie):
        return pd.to_datetime(serie, errors="coerce")

    texto = serie.fillna("").astype(str).str.strip()
    resultado = pd.Series(pd.NaT, index=serie.index, dtype="datetime64[ns]")

    formato_iso = texto.str.match(r"^\d{4}-\d{2}-\d{2}")
    if formato_iso.any():
        resultado.loc[formato_iso] = pd.to_datetime(
            texto.loc[formato_iso],
            errors="coerce",
            dayfirst=False,
        )

    formato_brasileiro = ~formato_iso & (texto != "")
    if formato_brasileiro.any():
        resultado.loc[formato_brasileiro] = pd.to_datetime(
            texto.loc[formato_brasileiro],
            errors="coerce",
            dayfirst=True,
        )

    return resultado


def aplicar_filtros(
    df,
    unidade=None,
    usuario=None,
    status=None,
    data_inicial=None,
    data_final=None,
):
    df_filtrado, _ = excluir_unidades_ignoradas(df)
    colunas = localizar_colunas(df_filtrado)

    if unidade and colunas["unidade"]:
        valores = serie_texto(
            df_filtrado,
            colunas["unidade"],
        )
        df_filtrado = df_filtrado[
            valores == unidade
        ].copy()

    if usuario and colunas["usuario"]:
        valores = serie_texto(
            df_filtrado,
            colunas["usuario"],
        )
        df_filtrado = df_filtrado[
            valores == usuario
        ].copy()

    if status and colunas["status"]:
        valores = serie_texto(
            df_filtrado,
            colunas["status"],
        )
        df_filtrado = df_filtrado[
            valores == status
        ].copy()

    if colunas["criado"]:
        df_filtrado["_data_criado"] = converter_datas(
            df_filtrado[colunas["criado"]]
        )

        if data_inicial:
            inicio = pd.to_datetime(data_inicial)
            df_filtrado = df_filtrado[
                df_filtrado["_data_criado"] >= inicio
            ].copy()

        if data_final:
            fim = (
                pd.to_datetime(data_final)
                + pd.Timedelta(days=1)
            )
            df_filtrado = df_filtrado[
                df_filtrado["_data_criado"] < fim
            ].copy()

    return df_filtrado


def mascara_sem_dados_atendimento(df):
    """
    Identifica linhas em que não existem dados essenciais do atendimento.

    O protocolo pode existir por ser gerado pelo sistema.
    São avaliados: Nome, Status, Criado Em, Atualizado Em,
    Atendido Em e Atendido Por.
    """
    if df.empty:
        return pd.Series(False, index=df.index)

    colunas = localizar_colunas(df)

    chaves = [
        "nome",
        "status",
        "criado",
        "atualizado",
        "unidade",
        "usuario",
    ]

    disponiveis = [
        colunas[chave]
        for chave in chaves
        if colunas.get(chave)
    ]

    if len(disponiveis) < 3:
        return pd.Series(False, index=df.index)

    sem_dados = pd.Series(True, index=df.index)

    for coluna in disponiveis:
        sem_dados = (
            sem_dados
            & (
                serie_texto(
                    df,
                    coluna,
                )
                == ""
            )
        )

    return sem_dados


def calcular_pendencias(df):
    """
    Considera como pendência cadastral:
    - registro sem dados do atendimento;
    - Nome Completo vazio, quando existem outros dados;
    - Atendido Por vazio;
    - Atendido Em vazio;
    - Criado Em ausente ou com data inválida.

    Rascunhos e protocolos duplicados não entram neste cálculo.
    """
    if df.empty:
        return 0

    colunas = localizar_colunas(df)

    sem_dados = mascara_sem_dados_atendimento(df)

    mascara = sem_dados.copy()

    if colunas["nome"]:
        nomes = serie_texto(
            df,
            colunas["nome"],
        )

        mascara = mascara | (
            (nomes == "")
            & (~sem_dados)
        )

    if colunas["usuario"]:
        usuarios = serie_texto(
            df,
            colunas["usuario"],
        )

        mascara = mascara | (
            (usuarios == "")
            & (~sem_dados)
        )

    if colunas["unidade"]:
        unidades = serie_texto(
            df,
            colunas["unidade"],
        )

        mascara = mascara | (
            (unidades == "")
            & (~sem_dados)
        )

    if colunas["criado"]:
        datas_texto = serie_texto(
            df,
            colunas["criado"],
        )

        datas_convertidas = converter_datas(
            df[colunas["criado"]]
        )

        data_invalida = (
            (
                (datas_texto == "")
                | datas_convertidas.isna()
            )
            & (~sem_dados)
        )

        mascara = mascara | data_invalida

    return int(mascara.sum())


def calcular_metricas(df):
    df, _ = excluir_unidades_ignoradas(df)
    colunas = localizar_colunas(df)

    total = len(df)

    # Pessoas únicas pelo campo Nome Completo.
    pessoas = contar_unicos(
        df,
        colunas["nome"],
    )

    mascara_sem_dados = mascara_sem_dados_atendimento(
        df
    )

    sem_dados = int(
        mascara_sem_dados.sum()
    )

    atendimentos_com_nome = 0
    sem_nome = 0

    if colunas["nome"]:
        nomes = serie_texto(
            df,
            colunas["nome"],
        )

        atendimentos_com_nome = int(
            (nomes != "").sum()
        )

        sem_nome = int(
            (
                (nomes == "")
                & (~mascara_sem_dados)
            ).sum()
        )

    unidades = contar_unicos(
        df,
        colunas["unidade"],
    )

    usuarios = contar_unicos(
        df,
        colunas["usuario"],
    )

    aguardando = 0
    rascunhos = 0

    if colunas["status"]:
        status = (
            serie_texto(
                df,
                colunas["status"],
            )
            .str.lower()
        )

        aguardando = int(
            (status == "aguardando").sum()
        )

        rascunhos = int(
            (status == "rascunho").sum()
        )

    recorrentes = 0

    if colunas["nome"]:
        nomes_normalizados = (
            serie_texto(
                df,
                colunas["nome"],
            )
            .str.lower()
        )

        nomes_normalizados = nomes_normalizados[
            nomes_normalizados != ""
        ]

        if not nomes_normalizados.empty:
            frequencias = (
                nomes_normalizados
                .value_counts()
            )

            recorrentes = int(
                (frequencias > 1).sum()
            )

    pendencias = calcular_pendencias(df)

    return {
        "total": total,
        "pessoas": pessoas,
        "atendimentos_com_nome": atendimentos_com_nome,
        "sem_nome": sem_nome,
        "sem_dados": sem_dados,
        "unidades": unidades,
        "usuarios": usuarios,
        "aguardando": aguardando,
        "rascunhos": rascunhos,
        "recorrentes": recorrentes,
        "pendencias": pendencias,
    }


def tabela_tempo(df, agrupamento):
    colunas = localizar_colunas(df)

    if not colunas["criado"]:
        return pd.DataFrame()

    if "_data_criado" in df.columns:
        datas = df["_data_criado"]
    else:
        datas = converter_datas(
            df[colunas["criado"]]
        )

    datas = datas.dropna()

    if datas.empty:
        return pd.DataFrame()

    base = pd.DataFrame(
        {
            "Data": datas,
        }
    )

    if agrupamento == "semana":
        base["Periodo"] = (
            base["Data"]
            .dt.to_period("W-SUN")
            .dt.start_time
        )

        agrupado = (
            base.groupby("Periodo")
            .size()
            .reset_index(
                name="Atendimentos"
            )
            .sort_values("Periodo")
        )

        agrupado["Label"] = (
            "Semana de "
            + agrupado["Periodo"]
            .dt.strftime("%d/%m/%Y")
        )

    elif agrupamento == "quinzena":
        base["Periodo"] = base["Data"].apply(
            lambda data: pd.Timestamp(
                year=data.year,
                month=data.month,
                day=1 if data.day <= 15 else 16,
            )
        )

        agrupado = (
            base.groupby("Periodo")
            .size()
            .reset_index(
                name="Atendimentos"
            )
            .sort_values("Periodo")
        )

        def rotulo_quinzena(data):
            if data.day == 1:
                return (
                    f"1ª quinzena "
                    f"{data.strftime('%m/%Y')}"
                )

            return (
                f"2ª quinzena "
                f"{data.strftime('%m/%Y')}"
            )

        agrupado["Label"] = (
            agrupado["Periodo"]
            .apply(rotulo_quinzena)
        )

    elif agrupamento == "mes":
        base["Periodo"] = (
            base["Data"]
            .dt.to_period("M")
            .dt.start_time
        )

        agrupado = (
            base.groupby("Periodo")
            .size()
            .reset_index(
                name="Atendimentos"
            )
            .sort_values("Periodo")
        )

        agrupado["Label"] = (
            agrupado["Periodo"]
            .dt.strftime("%m/%Y")
        )

    else:
        base["Periodo"] = (
            base["Data"].dt.normalize()
        )

        agrupado = (
            base.groupby("Periodo")
            .size()
            .reset_index(
                name="Atendimentos"
            )
            .sort_values("Periodo")
        )

        agrupado["Label"] = (
            agrupado["Periodo"]
            .dt.strftime("%d/%m/%Y")
        )

    return agrupado


