def ler_arquivo_upload(
    nome_arquivo,
    conteudo_upload,
):
    _, conteudo = (
        conteudo_upload.split(
            ",",
            1,
        )
    )

    dados = base64.b64decode(
        conteudo
    )

    extensao = (
        nome_arquivo
        .lower()
        .split(".")[-1]
    )

    if extensao == "csv":
        ultimo_erro = None

        for encoding in [
            "utf-8-sig",
            "utf-8",
            "cp1252",
            "latin1",
        ]:
            for separador in [
                ";",
                ",",
                "\t",
            ]:
                try:
                    tentativa = pd.read_csv(
                        io.BytesIO(dados),
                        encoding=encoding,
                        sep=separador,
                    )

                    if len(
                        tentativa.columns
                    ) > 1:
                        df = tentativa
                        break

                except Exception as erro:
                    ultimo_erro = erro
            else:
                continue

            break
        else:
            if ultimo_erro:
                raise ultimo_erro

            raise ValueError(
                "Não foi possível interpretar o CSV."
            )

    elif extensao == "xlsx":
        df = pd.read_excel(
            io.BytesIO(dados)
        )

    elif extensao in [
        "html",
        "htm",
    ]:
        tabelas = pd.read_html(
            io.BytesIO(dados)
        )

        if not tabelas:
            raise ValueError(
                "Nenhuma tabela foi encontrada no HTML."
            )

        df = tabelas[0]

    else:
        raise ValueError(
            "Formato não suportado. Use CSV, HTML ou XLSX."
        )

    df.columns = [
        str(col).strip()
        for col in df.columns
    ]

    return df


