def mascara_unidades_ignoradas(df):
    if df is None or df.empty:
        indice = df.index if isinstance(df, pd.DataFrame) else None
        return pd.Series(False, index=indice, dtype=bool)

    texto_unidade = pd.Series("", index=df.index, dtype="object")
    for coluna in df.columns:
        if normalizar_nome_mapa(coluna) not in COLUNAS_REFERENCIA_UNIDADE_CAIS:
            continue
        valores = serie_texto(df, coluna).map(normalizar_nome_mapa)
        texto_unidade = (texto_unidade + " " + valores).str.strip()

    mascara = pd.Series(False, index=df.index, dtype=bool)
    for termos in REGRAS_UNIDADES_IGNORADAS_CAIS:
        corresponde = pd.Series(True, index=df.index, dtype=bool)
        for termo in termos:
            corresponde = corresponde & texto_unidade.str.contains(
                termo,
                regex=False,
                na=False,
            )
        mascara = mascara | corresponde
    return mascara


def excluir_unidades_ignoradas(df):
    if df is None:
        return pd.DataFrame(), 0
    if df.empty:
        return df.copy(), 0

    mascara = mascara_unidades_ignoradas(df)
    quantidade = int(mascara.sum())
    return df.loc[~mascara].copy(), quantidade


def mascara_unidades_em_funcionamento(df):
    """Identifica unidades operacionais sem removê-las do cadastro ou mapa."""
    if df is None or df.empty:
        indice = df.index if isinstance(df, pd.DataFrame) else None
        return pd.Series(False, index=indice, dtype=bool)

    fase = (
        serie_texto(df, "Fase").map(normalizar_nome_mapa)
        if "Fase" in df.columns
        else pd.Series("", index=df.index, dtype="object")
    )
    situacao = (
        serie_texto(df, "Situação").map(normalizar_nome_mapa)
        if "Situação" in df.columns
        else pd.Series("", index=df.index, dtype="object")
    )
    descricao = (fase + " " + situacao).str.strip()

    operacional = (
        descricao.str.contains(r"\bem funcionamento\b", regex=True)
        | descricao.str.contains(r"\boperacional\b", regex=True)
        | descricao.str.contains(r"(?:^|\s)ativ[ao](?:\s|$)", regex=True)
    )
    indicacao_negativa = descricao.str.contains(
        (
            r"\bnao\b.{0,24}\b(?:funcionamento|operacional)\b"
            r"|\bfora de funcionamento\b"
            r"|\b(?:inativ|desativ|suspens|encerrad)[a-z]*\b"
        ),
        regex=True,
    )
    return operacional & ~indicacao_negativa


def contar_unidades_em_funcionamento(df):
    return int(mascara_unidades_em_funcionamento(df).sum())


def valor_generico_mapa(texto):
    return normalizar_nome_mapa(texto) in {
        "",
        "nao definido",
        "nao possui",
        "espaco nao definido",
    }


def localizar_coluna_mapa(df, *nomes):
    mapa = {
        normalizar_nome_mapa(coluna): coluna
        for coluna in df.columns
    }
    for nome in nomes:
        encontrada = mapa.get(normalizar_nome_mapa(nome))
        if encontrada is not None:
            return encontrada
    return None


def texto_celula_mapa(linha, coluna):
    if coluna is None:
        return ""
    valor = linha.get(coluna, "")
    if pd.isna(valor):
        return ""
    return re.sub(r"\s+", " ", str(valor)).strip()


def classificar_fase_mapa(situacao):
    texto = normalizar_nome_mapa(situacao)
    if "operacao" in texto:
        if "parcial" in texto:
            return "Em funcionamento parcial"
        return "Em funcionamento"
    if "implantacao" in texto:
        return "Em implantação"
    if "formalizacao" in texto:
        return "Em formalização"
    return "Não informado"


def normalizar_coordenada_mapa(valor, tipo, uf=""):
    if valor is None or pd.isna(valor) or str(valor).strip() == "":
        return None
    try:
        numero = float(str(valor).strip().replace(",", "."))
    except (TypeError, ValueError):
        return None

    if tipo == "longitude":
        if -75 <= numero <= -32:
            return round(numero, 7)
        candidatos = [
            numero / (10 ** potencia)
            for potencia in range(3, 9)
        ]
        validos = [
            candidato
            for candidato in candidatos
            if -75 <= candidato <= -32
        ]
        return round(validos[0], 7) if validos else None

    minimo, maximo = LIMITES_LATITUDE_UF.get(
        str(uf or "").strip().upper(),
        (-34.0, 6.0),
    )
    if minimo <= numero <= maximo:
        return round(numero, 7)
    candidatos = [
        numero / (10 ** potencia)
        for potencia in range(3, 9)
    ]
    validos = [
        candidato
        for candidato in candidatos
        if minimo <= candidato <= maximo
    ]
    if not validos:
        return None
    centro = (minimo + maximo) / 2
    escolhido = min(validos, key=lambda item: abs(item - centro))
    return round(escolhido, 7)


def padronizar_base_unidades_mapa(df):
    if df is None or df.empty:
        return pd.DataFrame(columns=COLUNAS_UNIDADES_MAPA)

    df = df.copy()
