def agora_brasilia():
    try:
        return datetime.now(ZoneInfo("America/Sao_Paulo"))
    except Exception:
        return datetime.now()


def ler_dataframe_store(conteudo):
    if not conteudo:
        return pd.DataFrame()
    try:
        dataframe = pd.read_json(
            io.StringIO(conteudo),
            orient="split",
        )
        dataframe, _ = excluir_unidades_ignoradas(dataframe)
        return dataframe
    except Exception:
        return pd.DataFrame()


def texto_filtros_relatorio(
    regiao=None,
    uf=None,
    unidade=None,
    data_inicial=None,
    data_final=None,
    agrupamento=None,
):
    filtros = []
    if regiao:
        filtros.append(f"Região: {regiao}")
    if uf:
        filtros.append(f"UF: {uf}")
    if unidade:
        filtros.append(f"Unidade/OSC: {unidade}")
    if data_inicial or data_final:
        inicio = (
            pd.to_datetime(data_inicial).strftime("%d/%m/%Y")
            if data_inicial
            else "início da base"
        )
        fim = (
            pd.to_datetime(data_final).strftime("%d/%m/%Y")
            if data_final
            else "data mais recente"
        )
        filtros.append(f"Período: {inicio} a {fim}")
    rotulos_agrupamento = {
        "dia": "diária",
        "semana": "semanal",
        "quinzena": "quinzenal",
        "mes": "mensal",
    }
    if agrupamento in rotulos_agrupamento:
        filtros.append(
            f"Evolução: {rotulos_agrupamento[agrupamento]}"
        )
    return " | ".join(filtros) if filtros else "Todos os dados disponíveis"


def filtrar_dados_dashboard_relatorio(
    dados_cais,
    dados_unidades,
    regiao=None,
    uf=None,
    unidade=None,
    data_inicial=None,
    data_final=None,
):
    base_unidades = ler_dataframe_store(dados_unidades)
    if base_unidades.empty:
        base_unidades = carregar_base_unidades_mapa()
    else:
        base_unidades = padronizar_base_unidades_mapa(base_unidades)

    atendimentos = ler_dataframe_store(dados_cais)
    integrada_total, _ = consolidar_atendimentos_no_mapa(
        base_unidades,
        dados_cais,
    )
    unidades_filtradas = integrada_total.copy()

    if regiao:
        unidades_filtradas = unidades_filtradas[
            unidades_filtradas["Região"] == regiao
        ].copy()
    if uf:
        unidades_filtradas = unidades_filtradas[
            unidades_filtradas["UF"] == uf
        ].copy()
    if unidade:
        unidades_filtradas = unidades_filtradas[
            (unidades_filtradas["Nome da Unidade"] == unidade)
            | (unidades_filtradas["Nome da OSC"] == unidade)
        ].copy()

    existe_filtro_geografico = bool(regiao or uf or unidade)
    if existe_filtro_geografico and not atendimentos.empty:
        colunas = localizar_colunas(atendimentos)
        coluna_unidade = colunas.get("unidade")
        if coluna_unidade:
            nomes_permitidos = set()
            for _, linha in unidades_filtradas.iterrows():
                nomes_permitidos.update(aliases_linha_mapa(linha))
                reconhecidos = str(
                    linha.get("Nomes reconhecidos no CAIS", "") or ""
                )
                nomes_permitidos.update(
                    normalizar_nome_mapa(nome)
                    for nome in reconhecidos.split("|")
                    if nome.strip()
                )
            nomes_atendimentos = serie_texto(
                atendimentos,
                coluna_unidade,
            ).map(normalizar_nome_mapa)
            atendimentos = atendimentos[
                nomes_atendimentos.isin(nomes_permitidos)
            ].copy()

    if not atendimentos.empty:
        atendimentos = aplicar_filtros(
            atendimentos,
            data_inicial=data_inicial,
            data_final=data_final,
        )

    base_geografica = unidades_filtradas[
        COLUNAS_UNIDADES_MAPA
    ].copy()
    dados_atendimentos_filtrados = (
        atendimentos.to_json(
            orient="split",
            force_ascii=False,
            date_format="iso",
        )
        if not atendimentos.empty
        else None
    )
    unidades_integradas, metricas_cruzamento = (
        consolidar_atendimentos_no_mapa(
            base_geografica,
            dados_atendimentos_filtrados,
        )
    )
    return unidades_integradas, atendimentos, metricas_cruzamento


def resumo_regional_dashboard(unidades):
    if unidades.empty:
        return pd.DataFrame(
            columns=["Região", "Unidades", "Pontos", "Atendimentos"]
        )
    base = unidades.copy()
    base["Região"] = base["Região"].fillna("").astype(str).str.strip()
    base.loc[base["Região"] == "", "Região"] = "Não informado"
    base["Ponto mapeável"] = (
        base["Latitude"].notna()
        & base["Longitude"].notna()
    ).astype(int)
    base["Unidade em funcionamento"] = (
        mascara_unidades_em_funcionamento(base).astype(int)
    )
    base["Atendimentos CAIS"] = pd.to_numeric(
        base["Atendimentos CAIS"],
        errors="coerce",
    ).fillna(0).astype(int)
    resumo = (
        base.groupby("Região", as_index=False)
        .agg(
            Unidades=("Unidade em funcionamento", "sum"),
            Pontos=("Ponto mapeável", "sum"),
            Atendimentos=("Atendimentos CAIS", "sum"),
        )
    )
    ordem = {nome: indice for indice, nome in enumerate(ORDEM_REGIOES_MAPA)}
    resumo["_ordem"] = resumo["Região"].map(ordem).fillna(99)
    return resumo.sort_values("_ordem").drop(columns="_ordem")


def remover_duplicidades_relatorio_pdf(atendimentos):
    """
    Mantém uma única ocorrência de cada atendimento no PDF.

    Primeiro elimina repetições do Número do Protocolo. Depois aplica o
    mesmo critério de possível duplicidade usado pela Auditoria: mesma
    pessoa, no mesmo dia, na mesma unidade, com o mesmo responsável e
    status. Registros sem dados suficientes para essa comparação são
    preservados.
    """
    if atendimentos is None:
        return pd.DataFrame(), {
            "protocolos_repetidos": 0,
            "possiveis_repetidos": 0,
            "total_desconsiderado": 0,
        }

    base = atendimentos.copy()
    resumo = {
        "protocolos_repetidos": 0,
        "possiveis_repetidos": 0,
        "total_desconsiderado": 0,
    }
    if base.empty:
        return base, resumo

    colunas = localizar_colunas(base)
    if colunas.get("protocolo"):
        protocolos = serie_texto(base, colunas["protocolo"])
        protocolos_normalizados = normalizar_serie_auditoria(protocolos)
        repeticoes_protocolo = (
            (protocolos_normalizados != "")
            & protocolos_normalizados.duplicated(keep="first")
        )
        resumo["protocolos_repetidos"] = int(
            repeticoes_protocolo.sum()
        )
        base = base.loc[~repeticoes_protocolo].copy()

    colunas = localizar_colunas(base)
    if colunas.get("nome") and colunas.get("criado"):
        registro_sem_dados = mascara_sem_dados_atendimento(base)
        nomes = normalizar_serie_auditoria(base[colunas["nome"]])
        datas = (
            converter_datas(base[colunas["criado"]])
            .dt.strftime("%Y-%m-%d")
            .fillna("")
        )
        unidades = (
            normalizar_serie_auditoria(base[colunas["unidade"]])
            if colunas.get("unidade")
            else pd.Series("", index=base.index)
        )
        usuarios = (
            normalizar_serie_auditoria(base[colunas["usuario"]])
            if colunas.get("usuario")
            else pd.Series("", index=base.index)
        )
        status = (
            normalizar_serie_auditoria(base[colunas["status"]])
            if colunas.get("status")
            else pd.Series("", index=base.index)
        )
        chave = pd.DataFrame(
            {
                "nome": nomes,
                "data": datas,
                "unidade": unidades,
                "usuario": usuarios,
                "status": status,
            },
            index=base.index,
        )
        chave_valida = (
            (chave["nome"] != "")
            & (chave["data"] != "")
            & (chave["unidade"] != "")
            & (chave["usuario"] != "")
            & (~registro_sem_dados)
        )
        possiveis_repeticoes = (
            chave_valida
            & chave.duplicated(
                subset=[
                    "nome",
                    "data",
                    "unidade",
                    "usuario",
                    "status",
                ],
                keep="first",
            )
        )
        resumo["possiveis_repetidos"] = int(
            possiveis_repeticoes.sum()
        )
        base = base.loc[~possiveis_repeticoes].copy()

    resumo["total_desconsiderado"] = (
        resumo["protocolos_repetidos"]
        + resumo["possiveis_repetidos"]
    )
    return base.reset_index(drop=True), resumo


def preparar_dados_relatorio_sem_duplicidades(unidades, atendimentos):
    atendimentos_unicos, resumo_duplicidades = (
        remover_duplicidades_relatorio_pdf(atendimentos)
    )
    if unidades is None:
        return pd.DataFrame(), atendimentos_unicos, resumo_duplicidades
    if unidades.empty:
        return unidades.copy(), atendimentos_unicos, resumo_duplicidades

    base_geografica = unidades[COLUNAS_UNIDADES_MAPA].copy()
    dados_unicos = (
        atendimentos_unicos.to_json(
            orient="split",
            force_ascii=False,
            date_format="iso",
        )
        if not atendimentos_unicos.empty
        else None
    )
    unidades_integradas, _ = consolidar_atendimentos_no_mapa(
        base_geografica,
        dados_unicos,
    )
    return unidades_integradas, atendimentos_unicos, resumo_duplicidades


def criar_mapa_dashboard_relatorio(unidades):
    pontos = unidades[
        unidades["Latitude"].notna()
        & unidades["Longitude"].notna()
    ].copy()
    if pontos.empty:
        return figura_vazia("Nenhuma unidade com coordenadas no recorte")

    pontos["Região"] = pontos["Região"].fillna("").astype(str).str.strip()
    pontos.loc[pontos["Região"] == "", "Região"] = "Não informado"
    centro, zoom = enquadramento_mapa(pontos)
    amplitude = max(
        float(pontos["Latitude"].max() - pontos["Latitude"].min()),
        float(pontos["Longitude"].max() - pontos["Longitude"].min()),
    )
    if amplitude > 20:
        centro = {"lat": -14.235, "lon": -51.9253}
        zoom = 3.0
    argumentos = {
        "data_frame": pontos,
        "lat": "Latitude",
        "lon": "Longitude",
        "color": "Região",
        "hover_name": "Nome para exibição",
        "hover_data": {
            "Município": True,
            "UF": True,
            "Fase": True,
            "Atendimentos CAIS": True,
            "Latitude": False,
            "Longitude": False,
        },
        "center": centro,
        "zoom": zoom,
        "color_discrete_map": CORES_REGIOES_MAPA,
        "category_orders": {"Região": ORDEM_REGIOES_MAPA},
    }
    if hasattr(px, "scatter_map"):
        figura = px.scatter_map(
            **argumentos,
            map_style="carto-positron",
        )
    else:
        figura = px.scatter_mapbox(**argumentos)
        figura.update_layout(mapbox_style="carto-positron")
    figura.update_traces(marker={"size": 7, "opacity": 0.84})
    figura.update_layout(
        autosize=True,
        height=None,
        margin={"l": 0, "r": 0, "t": 0, "b": 0},
        legend={
            "title": {"text": "Região"},
            "orientation": "h",
            "yanchor": "bottom",
            "y": 0.01,
            "xanchor": "left",
            "x": 0.01,
            "bgcolor": "rgba(255,255,255,0.85)",
        },
        uirevision="mapa-dashboard-relatorio",
    )
    return figura


def criar_grafico_regional_dashboard(unidades):
    resumo = resumo_regional_dashboard(unidades)
    if resumo.empty:
        return figura_vazia("Nenhum dado regional no recorte")
    resumo = resumo.sort_values("Unidades", ascending=True)
    figura = px.bar(
        resumo,
        x="Unidades",
        y="Região",
        orientation="h",
        color="Região",
        color_discrete_map=CORES_REGIOES_MAPA,
        text="Unidades",
        template="plotly_white",
        hover_data={"Pontos": True, "Atendimentos": True},
    )
    figura.update_traces(
        textposition="inside",
        insidetextanchor="end",
        textfont={"color": "white"},
        cliponaxis=False,
    )
    figura.update_layout(
        autosize=True,
        showlegend=False,
        xaxis_title="Unidades em funcionamento",
        yaxis_title=None,
        margin={"l": 15, "r": 45, "t": 15, "b": 45},
        height=None,
    )
    return figura


def criar_grafico_top_unidades_dashboard(atendimentos, limite=12):
    if atendimentos.empty:
        return figura_vazia("Importe a base do CAIS para gerar o ranking")
    colunas = localizar_colunas(atendimentos)
    coluna_unidade = colunas.get("unidade")
    if not coluna_unidade:
        return figura_vazia("Campo de unidade/OSC não identificado")
    contagem = serie_texto(atendimentos, coluna_unidade)
    contagem = contagem[contagem != ""].value_counts().head(limite)
    if contagem.empty:
        return figura_vazia("Nenhuma unidade/OSC identificada")
    tabela = contagem.reset_index()
    tabela.columns = ["Unidade / OSC", "Atendimentos"]
    tabela = tabela.sort_values("Atendimentos", ascending=True)
    tabela["Rótulo"] = tabela["Unidade / OSC"].apply(
        lambda nome: (
            str(nome)
            if len(str(nome)) <= 68
            else f"{str(nome)[:65].rstrip()}…"
        )
    )
    figura = px.bar(
        tabela,
        x="Atendimentos",
        y="Rótulo",
        orientation="h",
        text="Atendimentos",
        template="plotly_white",
        hover_name="Unidade / OSC",
        hover_data={"Rótulo": False},
    )
    figura.update_traces(
        textposition="inside",
        insidetextanchor="end",
        textfont={"color": "white"},
        marker_color="#1351B4",
        cliponaxis=False,
    )
    figura.update_layout(
        autosize=True,
        showlegend=False,
        xaxis_title="Atendimentos",
        yaxis_title=None,
        margin={"l": 20, "r": 20, "t": 15, "b": 45},
        height=None,
    )
    figura.update_yaxes(automargin=True, tickfont={"size": 10})
    return figura


