def grafico_evolucao_unidades(
    df,
    agrupamento,
):
    if df.empty:
        return figura_vazia(
            "Nenhum atendimento encontrado"
        )

    colunas = localizar_colunas(
        df
    )

    if (
        not colunas["unidade"]
        or not colunas["criado"]
    ):
        return figura_vazia(
            "Colunas de unidade ou data não encontradas"
        )

    base = pd.DataFrame(
        {
            "Unidade / OSC": serie_texto(
                df,
                colunas["unidade"],
            ),
            "Data": converter_datas(
                df[colunas["criado"]]
            ),
        }
    )

    base = base[
        (
            base["Unidade / OSC"]
            != ""
        )
        & base["Data"].notna()
    ].copy()

    if base.empty:
        return figura_vazia(
            "Nenhuma data válida encontrada"
        )

    if agrupamento == "semana":
        base["Periodo"] = (
            base["Data"]
            .dt.to_period("W-SUN")
            .dt.start_time
        )

        base["Label"] = (
            "Semana de "
            + base["Periodo"]
            .dt.strftime("%d/%m/%Y")
        )

    elif agrupamento == "quinzena":
        base["Periodo"] = base[
            "Data"
        ].apply(
            lambda data: pd.Timestamp(
                year=data.year,
                month=data.month,
                day=(
                    1
                    if data.day <= 15
                    else 16
                ),
            )
        )

        base["Label"] = base[
            "Periodo"
        ].apply(
            lambda data: (
                (
                    "1ª quinzena "
                    if data.day == 1
                    else "2ª quinzena "
                )
                + data.strftime(
                    "%m/%Y"
                )
            )
        )

    elif agrupamento == "mes":
        base["Periodo"] = (
            base["Data"]
            .dt.to_period("M")
            .dt.start_time
        )

        base["Label"] = (
            base["Periodo"]
            .dt.strftime("%m/%Y")
        )

    else:
        base["Periodo"] = (
            base["Data"]
            .dt.normalize()
        )

        base["Label"] = (
            base["Periodo"]
            .dt.strftime("%d/%m/%Y")
        )

    # Mantém legibilidade do gráfico quando há muitas unidades:
    # mostra no gráfico as 10 com maior volume, mas a tabela
    # consolidada continua contendo todas.
    ranking_unidades = (
        base["Unidade / OSC"]
        .value_counts()
    )

    unidades_grafico = (
        ranking_unidades
        .head(10)
        .index
        .tolist()
    )

    base = base[
        base["Unidade / OSC"]
        .isin(
            unidades_grafico
        )
    ].copy()

    agrupado = (
        base.groupby(
            [
                "Periodo",
                "Label",
                "Unidade / OSC",
            ]
        )
        .size()
        .reset_index(
            name="Atendimentos"
        )
        .sort_values(
            [
                "Periodo",
                "Unidade / OSC",
            ]
        )
    )

    figura = px.line(
        agrupado,
        x="Label",
        y="Atendimentos",
        color="Unidade / OSC",
        markers=True,
        template="plotly_white",
    )

    figura.update_layout(
        xaxis_title=None,
        yaxis_title="Atendimentos",
        legend_title_text="Unidade / OSC",
        margin=dict(
            l=20,
            r=20,
            t=20,
            b=20,
        ),
        height=430,
    )

    return figura


