# ============================================================
# CALLBACK - NAVEGAÇÃO
# ============================================================

@app.callback(
    [
        Output("navbar-container", "children"),
        Output("page-content", "children"),
    ],
    [
        Input("url", "pathname"),
        Input("auth-refresh", "data"),
    ],
)
def navegar_paginas(pathname, auth_refresh):
    if pathname == "/logout":
        session.clear()
        return None, criar_login_layout()

    if not bool(session.get("autenticado", False)):
        return None, criar_login_layout()

    if pathname == "/atendimentos":
        pagina = atendimentos_layout
    elif pathname == "/unidades":
        pagina = unidades_layout
    elif pathname == "/mapa-unidades":
        pagina = mapa_unidades_layout
    elif pathname == "/usuarios":
        pagina = usuarios_layout
    elif pathname == "/auditoria":
        pagina = auditoria_layout
    elif pathname == "/transferencias":
        pagina = transferencias_layout
    elif pathname == "/base":
        pagina = base_layout
    elif pathname == "/relatorios":
        pagina = relatorios_layout
    else:
        pagina = home_layout

    return navbar, pagina


# ============================================================
# CALLBACK - LOGIN
# ============================================================

@app.callback(
    [
        Output("mensagem-login", "children"),
        Output("auth-refresh", "data"),
        Output("url", "pathname", allow_duplicate=True),
    ],
    [
        Input("botao-login", "n_clicks"),
        Input("login-senha", "n_submit"),
    ],
    [
        State("login-usuario", "value"),
        State("login-senha", "value"),
        State("auth-refresh", "data"),
    ],
    prevent_initial_call=True,
)
def realizar_login(n_clicks, n_submit, usuario, senha, auth_refresh):
    if not SENHA_LOGIN:
        return (
            dbc.Alert(
                [
                    html.Strong("Login ainda não configurado. "),
                    "Defina APP_USERNAME e APP_PASSWORD nas variáveis do sistema/Railway.",
                ],
                color="warning",
                className="py-2 mb-0",
            ),
            auth_refresh or 0,
            no_update,
        )

    usuario_ok = hmac.compare_digest(str(usuario or "").strip(), USUARIO_LOGIN)
    senha_ok = hmac.compare_digest(str(senha or ""), SENHA_LOGIN)

    if usuario_ok and senha_ok:
        session.clear()
        session["autenticado"] = True
        session["usuario"] = USUARIO_LOGIN
        return None, int(auth_refresh or 0) + 1, "/"

    return (
        dbc.Alert(
            [html.I(className="fa-solid fa-circle-exclamation me-2"), "Usuário ou senha inválidos."],
            color="danger",
            className="py-2 mb-0",
        ),
        auth_refresh or 0,
        no_update,
    )


