# ============================================================
# CALLBACK - PROCESSAMENTO DO UPLOAD
# ============================================================

@app.callback(
    [
        Output(
            "mensagem-upload-home",
            "children",
        ),
        Output(
            "dados-cais",
            "data",
        ),
    ],
    Input(
        "upload-dados-home",
        "contents",
    ),
    State(
        "upload-dados-home",
        "filename",
    ),
    prevent_initial_call=True,
)
def processar_upload_home(
    conteudo_upload,
    nome_arquivo,
):
    if not conteudo_upload:
        return (
            None,
            None,
        )

    try:
        # dcc.Upload com multiple=True devolve listas.
        # A normalização abaixo também mantém compatibilidade
        # caso apenas um arquivo seja recebido.
        conteudos = (
            conteudo_upload
            if isinstance(
                conteudo_upload,
                list,
            )
            else [
                conteudo_upload
            ]
        )

        nomes = (
            nome_arquivo
            if isinstance(
                nome_arquivo,
                list,
            )
            else [
                nome_arquivo
            ]
        )

        colunas_necessarias = {
            "número do protocolo",
            "nome completo",
            "status do atendimento",
            "criado em",
            "atualizado em",
            "atendido por",
        }
        alternativas_unidade = {
            "atendido em",
            "unidade / osc",
            "unidade/osc",
            "nome da unidade",
            "nome da osc",
        }

        dataframes_validos = []
        arquivos_validos = []
        conteudos_validos = []
        arquivos_ignorados = []

        for conteudo, nome in zip(
            conteudos,
            nomes,
        ):
            try:
                df_arquivo = (
                    ler_arquivo_upload(
                        nome,
                        conteudo,
                    )
                )

                colunas_normalizadas = {
                    str(col)
                    .strip()
                    .lower()
                    for col in df_arquivo.columns
                }

                eh_atendimento = (
                    colunas_necessarias.issubset(colunas_normalizadas)
                    and bool(
                        alternativas_unidade
                        & colunas_normalizadas
                    )
                )

                if not eh_atendimento:
                    arquivos_ignorados.append(
                        (
                            f"{nome}: não corresponde "
                            "à tabela de atendimentos"
                        )
                    )
                    continue

                dataframes_validos.append(
                    df_arquivo
                )

                arquivos_validos.append(
                    nome
                )

                conteudos_validos.append(
                    conteudo
                )

            except Exception as erro_arquivo:
                arquivos_ignorados.append(
                    (
                        f"{nome}: "
                        f"{erro_arquivo}"
                    )
                )

        if not dataframes_validos:
            return (
                dbc.Alert(
                    [
                        html.I(
                            className=(
                                "fa-solid "
                                "fa-triangle-exclamation "
                                "me-2"
                            )
                        ),
                        html.Strong(
                            "Nenhum arquivo de atendimentos válido foi identificado."
                        ),
                        html.Br(),
                        html.Small(
                            (
                                "Confira se os arquivos exportados "
                                "possuem as colunas esperadas do CAIS."
                            )
                        ),
                    ],
                    color="danger",
                    className="mt-3 mb-0",
                ),
                None,
            )

        df = pd.concat(
            dataframes_validos,
            ignore_index=True,
            sort=False,
        )

        df, registros_unidades_ignorados = (
            excluir_unidades_ignoradas(df)
        )

        if df.empty:
            raise ValueError(
                "A base contém somente registros de unidades excluídas do monitoramento."
            )

        quantidade_linhas = len(
            df
        )

        quantidade_colunas = len(
            df.columns
        )

        quantidade_arquivos = len(
            arquivos_validos
        )

        colunas_encontradas = list(
            df.columns
        )

        colunas = localizar_colunas(
            df
        )

        quantidade_unidades = contar_unicos(
            df,
            colunas["unidade"],
        )

        dados_cais = df.to_json(
            orient="split",
            date_format="iso",
        )

        importacao_id = None
        erro_armazenamento = None

        try:
            importacao_id = registrar_importacao(
                tipo="Atendimentos",
                nomes_arquivos=arquivos_validos,
                conteudos_arquivos=conteudos_validos,
                dataframe=df,
            )
        except Exception as erro_salvar:
            erro_armazenamento = str(erro_salvar)

        mensagem_conteudo = [
            html.I(
                className=(
                    "fa-solid "
                    "fa-circle-check "
                    "me-2"
                )
            ),

            html.Strong(
                (
                    "Base de atendimentos "
                    "processada com sucesso!"
                )
            ),

            html.Br(),

            html.Small(
                (
                    f"{quantidade_arquivos} arquivo(s) "
                    f"consolidado(s), "
                    f"{quantidade_linhas} linhas e "
                    f"{quantidade_colunas} colunas."
                )
            ),

            html.Br(),

            html.Small(
                (
                    f"{quantidade_unidades} unidade(s) / "
                    "OSC(s) identificada(s) em "
                    "'Atendido Em'."
                )
            ),

            html.Br(),

            html.Small(
                [
                    html.Strong(
                        "Arquivos carregados: "
                    ),
                    ", ".join(
                        arquivos_validos
                    ),
                ]
            ),

            html.Br(),

            html.Small(
                [
                    html.Strong(
                        "Colunas identificadas: "
                    ),
                    ", ".join(
                        colunas_encontradas
                    ),
                ]
            ),
        ]

        if registros_unidades_ignorados:
            mensagem_conteudo.extend(
                [
                    html.Br(),
                    html.Small(
                        [
                            html.Strong(
                                "Registros de unidades excluídas: "
                            ),
                            (
                                f"{registros_unidades_ignorados}. "
                                "Eles não entram nos indicadores, gráficos, "
                                "mapa, tabelas ou relatórios."
                            ),
                        ]
                    ),
                ]
            )

        if importacao_id:
            mensagem_conteudo.extend(
                [
                    html.Br(),
                    html.Small(
                        [
                            html.I(className="fa-solid fa-database me-1"),
                            html.Strong("Salvo permanentemente: "),
                            f"importação #{importacao_id} na Base de Dados.",
                        ]
                    ),
                ]
            )

        if erro_armazenamento:
            mensagem_conteudo.extend(
                [
                    html.Hr(className="my-2"),
                    html.Small(
                        [
                            html.Strong("Atenção: "),
                            (
                                "os dados foram carregados no painel, mas não foi possível "
                                f"salvar a cópia permanente: {erro_armazenamento}"
                            ),
                        ]
                    ),
                ]
            )

        if arquivos_ignorados:
            mensagem_conteudo.extend(
                [
                    html.Hr(
                        className="my-2"
                    ),
                    html.Small(
                        [
                            html.Strong(
                                "Arquivos ignorados: "
                            ),
                            " | ".join(
                                arquivos_ignorados
                            ),
                        ]
                    ),
                ]
            )

        mensagem = dbc.Alert(
            mensagem_conteudo,
            color=(
                "warning"
                if arquivos_ignorados
                else "success"
            ),
            className="mt-3 mb-0",
        )

        return (
            mensagem,
            dados_cais,
        )

    except Exception as erro:
        return (
            dbc.Alert(
                [
                    html.I(
                        className=(
                            "fa-solid "
                            "fa-triangle-exclamation "
                            "me-2"
                        )
                    ),
                    html.Strong(
                        "Erro ao processar os arquivos."
                    ),
                    html.Br(),
                    html.Small(
                        str(erro)
                    ),
                ],
                color="danger",
                className="mt-3 mb-0",
            ),
            None,
        )


# ============================================================
# CALLBACK - FOTOS DO CARROSSEL DA PÁGINA INICIAL
# ============================================================

@app.callback(
    [
        Output("area-carrossel-inicio", "children"),
        Output("mensagem-upload-fotos-inicio", "children"),
    ],
    [
        Input("upload-fotos-carrossel-inicio", "contents"),
        Input("inicializar-carrossel-inicio", "n_intervals"),
    ],
    State("upload-fotos-carrossel-inicio", "filename"),
)
def processar_fotos_carrossel_inicio(conteudos, _n_intervalos, nomes):
    if ctx.triggered_id != "upload-fotos-carrossel-inicio" or not conteudos:
        return criar_area_carrossel_inicio(), no_update

    salvas, ignoradas = salvar_fotos_carrossel(conteudos, nomes)
    partes_mensagem = []

    if salvas:
        partes_mensagem.extend(
            [
                html.I(className="fa-solid fa-circle-check me-2"),
                html.Strong(
                    f"{len(salvas)} foto(s) adicionada(s) ao carrossel."
                ),
            ]
        )

    if ignoradas:
        if partes_mensagem:
            partes_mensagem.append(html.Hr(className="my-2"))
        partes_mensagem.extend(
            [
                html.Strong("Arquivo(s) não adicionados:"),
                html.Ul(
                    [html.Li(item) for item in ignoradas],
                    className="mb-0 mt-1 small",
                ),
            ]
        )

    cor = "success" if salvas and not ignoradas else "warning"
    if ignoradas and not salvas:
        cor = "danger"

    return (
        criar_area_carrossel_inicio(),
        dbc.Alert(partes_mensagem, color=cor, className="mb-0"),
    )


