@app.callback(
    [
        Output("grafico-regioes-mapa", "figure"),
        Output("destaque-regiao-mapa", "children"),
    ],
    [
        Input("dados-unidades-mapa", "data"),
        Input("dados-cais", "data"),
        Input("filtro-regiao-mapa", "value"),
        Input("filtro-uf-mapa", "value"),
        Input("filtro-fase-mapa", "value"),
        Input("filtro-unidade-mapa", "value"),
        Input("metrica-regional-mapa", "value"),
    ],
)
def atualizar_resumo_regional_mapa(
    dados_unidades,
    dados_cais,
    regiao,
    uf,
    fase,
    unidade,
    metrica,
):
    if not dados_unidades:
        return (
            figura_vazia("Aguardando a base geográfica das unidades."),
            None,
        )

    base = pd.read_json(io.StringIO(dados_unidades), orient="split")
    base = padronizar_base_unidades_mapa(base)
    integrada, _ = consolidar_atendimentos_no_mapa(base, dados_cais)
    filtrada = integrada.copy()

    if regiao:
        filtrada = filtrada[filtrada["Região"] == regiao].copy()
    if uf:
        filtrada = filtrada[filtrada["UF"] == uf].copy()
    if fase:
        filtrada = filtrada[filtrada["Fase"] == fase].copy()
    if unidade:
        filtrada = filtrada[
            (filtrada["Nome da Unidade"] == unidade)
            | (filtrada["Nome da OSC"] == unidade)
        ].copy()

    if filtrada.empty:
        return (
            figura_vazia("Nenhum registro corresponde aos filtros selecionados."),
            dbc.Alert(
                "Não há dados regionais para o recorte selecionado.",
                color="light",
                className="border rounded-4 mb-0",
            ),
        )

    filtrada["Região"] = filtrada["Região"].fillna("").astype(str).str.strip()
    filtrada.loc[filtrada["Região"] == "", "Região"] = "Não informado"
    filtrada["Atendimentos CAIS"] = pd.to_numeric(
        filtrada["Atendimentos CAIS"],
        errors="coerce",
    ).fillna(0).astype(int)
    filtrada["Ponto mapeável"] = (
        filtrada["Latitude"].notna()
        & filtrada["Longitude"].notna()
    ).astype(int)
    filtrada["Unidade em funcionamento"] = (
        mascara_unidades_em_funcionamento(filtrada).astype(int)
    )

    resumo = (
        filtrada.groupby("Região", as_index=False)
        .agg(
            Unidades=("Unidade em funcionamento", "sum"),
            Pontos=("Ponto mapeável", "sum"),
            Atendimentos=("Atendimentos CAIS", "sum"),
        )
    )

    configuracoes = {
        "unidades": ("Unidades", "Unidades em funcionamento"),
        "pontos": ("Pontos", "Pontos mapeáveis"),
        "atendimentos": ("Atendimentos", "Atendimentos CAIS"),
    }
    coluna_valor, rotulo = configuracoes.get(
        metrica,
        configuracoes["unidades"],
    )
    resumo = resumo.sort_values(
        [coluna_valor, "Região"],
        ascending=[True, False],
    )

    figura = px.bar(
        resumo,
        x=coluna_valor,
        y="Região",
        orientation="h",
        color="Região",
        color_discrete_map=CORES_REGIOES_MAPA,
        text=coluna_valor,
        labels={coluna_valor: rotulo, "Região": "Região"},
        hover_data={
            "Unidades": True,
            "Pontos": True,
            "Atendimentos": True,
        },
    )
    figura.update_traces(
        textposition="outside",
        cliponaxis=False,
        hovertemplate=(
            "<b>%{y}</b><br>"
            + rotulo
            + ": %{x:,.0f}<extra></extra>"
        ),
    )
    figura.update_layout(
        autosize=True,
        showlegend=False,
        margin={"l": 15, "r": 45, "t": 20, "b": 45},
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        xaxis={
            "title": rotulo,
            "showgrid": True,
            "gridcolor": "#E7ECF3",
            "rangemode": "tozero",
        },
        yaxis={"title": ""},
        font={"color": "#071D41"},
    )

    maior_valor = int(resumo[coluna_valor].max())
    if maior_valor == 0:
        destaque = dbc.Alert(
            [
                html.I(className="fa-solid fa-circle-info me-2"),
                f"Nenhum valor contabilizado em {rotulo.lower()} neste recorte.",
            ],
            color="light",
            className="border rounded-4 mb-0 py-2",
        )
        return figura, destaque

    lideres = resumo.loc[
        resumo[coluna_valor] == maior_valor,
        "Região",
    ].tolist()
    nomes_lideres = " e ".join(lideres)
    verbo = "lideram" if len(lideres) > 1 else "lidera"
    destaque = dbc.Alert(
        [
            html.I(className="fa-solid fa-chart-column me-2"),
            html.Strong(f"{nomes_lideres} {verbo} o recorte: "),
            f"{maior_valor} em {rotulo.lower()}.",
        ],
        color="primary",
        className="rounded-4 mb-0 py-2",
    )
    return figura, destaque


@app.callback(
    [
        Output("mapa-unidades-cais", "figure"),
        Output("card-registros-mapa", "children"),
        Output("card-pontos-mapa", "children"),
        Output("card-atendimentos-mapa", "children"),
        Output("card-sem-coordenadas-mapa", "children"),
        Output("mensagem-cruzamento-mapa", "children"),
        Output("tabela-unidades-mapa", "columns"),
        Output("tabela-unidades-mapa", "data"),
    ],
    [
        Input("dados-unidades-mapa", "data"),
        Input("dados-cais", "data"),
        Input("filtro-regiao-mapa", "value"),
        Input("filtro-uf-mapa", "value"),
        Input("filtro-fase-mapa", "value"),
        Input("filtro-unidade-mapa", "value"),
        Input("estilo-mapa-unidades", "value"),
        Input("modo-pontos-mapa", "value"),
        Input("agrupar-pontos-mapa", "value"),
    ],
)
def atualizar_mapa_unidades(
    dados_unidades,
    dados_cais,
    regiao,
    uf,
    fase,
    unidade,
    estilo,
    modo_pontos,
    agrupar,
):
    if not dados_unidades:
        vazio = figura_vazia("Aguardando a base geográfica das unidades.")
        return vazio, "0", "0", "0", "0", None, [], []

    base = pd.read_json(io.StringIO(dados_unidades), orient="split")
    base = padronizar_base_unidades_mapa(base)
    integrada, metricas = consolidar_atendimentos_no_mapa(base, dados_cais)
    filtrada = integrada.copy()

    if regiao:
        filtrada = filtrada[filtrada["Região"] == regiao].copy()
    if uf:
        filtrada = filtrada[filtrada["UF"] == uf].copy()
    if fase:
        filtrada = filtrada[filtrada["Fase"] == fase].copy()
    if unidade:
        filtrada = filtrada[
            (filtrada["Nome da Unidade"] == unidade)
            | (filtrada["Nome da OSC"] == unidade)
        ].copy()

    pontos = filtrada[
        filtrada["Latitude"].notna()
        & filtrada["Longitude"].notna()
    ].copy()
    sem_coordenadas = int(len(filtrada) - len(pontos))

    if pontos.empty:
        figura = figura_vazia(
            "Nenhuma unidade com coordenadas corresponde aos filtros."
        )
    else:
        pontos["Tamanho do ponto"] = (
            pd.to_numeric(
                pontos["Atendimentos CAIS"],
                errors="coerce",
            ).fillna(0) + 1
        )
        centro, zoom = enquadramento_mapa(pontos)
        argumentos = {
            "data_frame": pontos,
            "lat": "Latitude",
            "lon": "Longitude",
            "color": "Região",
            "hover_name": "Nome para exibição",
            "hover_data": {
                "Região": True,
                "Nome da OSC": True,
                "Nome da Unidade": True,
                "Município": True,
                "UF": True,
                "Endereço": True,
                "Situação": True,
                "Atendimentos CAIS": True,
                "Nomes reconhecidos no CAIS": True,
                "Latitude": False,
                "Longitude": False,
                "Tamanho do ponto": False,
            },
            "center": centro,
            "zoom": zoom,
            "color_discrete_map": CORES_REGIOES_MAPA,
            "category_orders": {"Região": ORDEM_REGIOES_MAPA},
        }
        if modo_pontos == "atendimentos":
            argumentos["size"] = "Tamanho do ponto"
            argumentos["size_max"] = 18

        if hasattr(px, "scatter_map"):
            figura = px.scatter_map(
                **argumentos,
                map_style=estilo or "carto-positron",
            )
        else:
            figura = px.scatter_mapbox(**argumentos)
            figura.update_layout(
                mapbox_style=estilo or "carto-positron"
            )

        if modo_pontos != "atendimentos":
            figura.update_traces(
                marker={"size": 7, "opacity": 0.82}
            )
        else:
            figura.update_traces(marker={"opacity": 0.82})

        if agrupar:
            try:
                figura.update_traces(
                    cluster={
                        "enabled": True,
                        "maxzoom": 9,
                        "step": 25,
                    }
                )
            except Exception:
                pass

        figura.update_layout(
            autosize=True,
            margin={"l": 0, "r": 0, "t": 0, "b": 0},
            legend={
                "title": {"text": "Região"},
                "orientation": "h",
                "yanchor": "bottom",
                "y": 0.01,
                "xanchor": "left",
                "x": 0.01,
                "bgcolor": "rgba(255,255,255,0.82)",
            },
            uirevision=(
                f"{regiao}|{uf}|{fase}|{unidade}|{estilo}|{modo_pontos}"
            ),
        )

    if not dados_cais:
        mensagem = dbc.Alert(
            [
                html.I(className="fa-solid fa-circle-info me-2"),
                (
                    "O cadastro geográfico está sendo exibido. Importe a base "
                    "de atendimentos na página inicial para acrescentar os "
                    "quantitativos do CAIS aos pontos."
                ),
            ],
            color="light",
            className="border rounded-4 mb-0",
        )
    else:
        nao_reconhecidos = metricas["nao_reconhecidos"]
        detalhes = []
        if nao_reconhecidos:
            detalhes.append(
                html.Details(
                    [
                        html.Summary(
                            f"Ver {len(nao_reconhecidos)} nome(s) não reconhecido(s)",
                            className="fw-semibold mt-2",
                        ),
                        html.Ul(
                            [html.Li(nome) for nome in nao_reconhecidos],
                            className="mb-0 mt-2",
                        ),
                    ]
                )
            )
        mensagem = dbc.Alert(
            [
                html.I(className="fa-solid fa-link me-2"),
                html.Strong("Cruzamento com a base do CAIS: "),
                (
                    f"{metricas['nomes_vinculados']} de "
                    f"{metricas['nomes_total']} nome(s) de unidade/OSC reconhecido(s), "
                    f"representando {metricas['atendimentos_vinculados']} de "
                    f"{metricas['total_atendimentos']} atendimento(s)."
                ),
                *detalhes,
            ],
            color="warning" if nao_reconhecidos else "success",
            className="rounded-4 mb-0",
        )

    colunas_tabela = [
        "Região",
        "UF",
        "Nome da OSC",
        "Nome da Unidade",
        "Município",
        "Endereço",
        "Fase",
        "Atendimentos CAIS",
        "Nomes reconhecidos no CAIS",
        "Mapeável",
    ]
    tabela = filtrada[colunas_tabela].copy()
    tabela["Atendimentos CAIS"] = pd.to_numeric(
        tabela["Atendimentos CAIS"],
        errors="coerce",
    ).fillna(0).astype(int)

    return (
        figura,
        str(contar_unidades_em_funcionamento(filtrada)),
        str(len(pontos)),
        str(metricas["atendimentos_vinculados"]),
        str(sem_coordenadas),
        mensagem,
        [{"name": coluna, "id": coluna} for coluna in colunas_tabela],
        tabela.to_dict("records"),
    )


