def criar_grafico_regiao_transferencias(base):
    if base.empty:
        return figura_vazia("Nenhuma transferência corresponde aos filtros.")

    dados = base.copy()
    dados["Região"] = dados["Região"].replace("", "Não informado")
    resumo = (
        dados.groupby("Região", as_index=False)[
            ["Valor Global", "Valor Desembolsado", "Valor a Desembolsar"]
        ]
        .sum()
    )
    longo = resumo.melt(
        id_vars="Região",
        var_name="Indicador",
        value_name="Valor",
    )
    longo["Valor em milhões"] = longo["Valor"] / 1_000_000
    figura = px.bar(
        longo,
        x="Região",
        y="Valor em milhões",
        color="Indicador",
        barmode="group",
        template="plotly_white",
        color_discrete_map={
            "Valor Global": COR_CIDADANIA_AZUL,
            "Valor Desembolsado": COR_CIDADANIA_VERDE,
            "Valor a Desembolsar": COR_CIDADANIA_VERMELHO,
        },
        category_orders={"Região": ORDEM_REGIOES_MAPA + ["Nacional"]},
    )
    figura.update_traces(
        hovertemplate=(
            "<b>%{x}</b><br>%{fullData.name}: "
            "R$ %{y:.2f} milhões<extra></extra>"
        )
    )
    figura.update_layout(
        autosize=True,
        xaxis_title=None,
        yaxis_title="R$ milhões",
        legend_title_text="",
        legend={"orientation": "h", "y": 1.12, "x": 0},
        margin={"l": 25, "r": 20, "t": 50, "b": 35},
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
    )
    return figura


def criar_grafico_status_transferencias(base):
    if base.empty:
        return figura_vazia("Nenhuma transferência corresponde aos filtros.")
    status = base["Status"].replace("", "Não informado").value_counts()
    figura = px.pie(
        names=status.index,
        values=status.values,
        hole=0.58,
        template="plotly_white",
        color_discrete_sequence=[
            COR_CIDADANIA_VERDE,
            COR_CIDADANIA_AZUL,
            COR_CIDADANIA_VERMELHO,
            "#0C326F",
            "#2E7D32",
            "#B3261E",
        ],
    )
    figura.update_traces(
        textposition="inside",
        textinfo="percent+label",
        hovertemplate="<b>%{label}</b><br>%{value} instrumento(s)<extra></extra>",
    )
    figura.update_layout(
        autosize=True,
        showlegend=False,
        margin={"l": 15, "r": 15, "t": 15, "b": 15},
        paper_bgcolor="rgba(0,0,0,0)",
    )
    return figura


def criar_grafico_convenentes_transferencias(
    base,
    limite=15,
    modo="valores",
):
    if base.empty:
        return figura_vazia("Nenhuma transferência corresponde aos filtros.")
    modo = "percentual" if modo == "percentual" else "valores"
    resumo = (
        base.groupby("Convenente / OSC", as_index=False)[
            ["Valor Global", "Valor Desembolsado", "Valor a Desembolsar"]
        ]
        .sum()
        .nlargest(limite, "Valor Global")
        .sort_values("Valor Global", ascending=True)
    )
    resumo["Valor global em milhões"] = resumo["Valor Global"] / 1_000_000
    resumo["Valor desembolsado em milhões"] = (
        resumo["Valor Desembolsado"] / 1_000_000
    )
    resumo["Percentual desembolsado"] = (
        resumo["Valor Desembolsado"]
        .div(resumo["Valor Global"].where(resumo["Valor Global"] != 0))
        .fillna(0.0)
        .clip(lower=0.0)
    )
    resumo["Percentual visual"] = resumo[
        "Percentual desembolsado"
    ].clip(lower=0.0, upper=1.0)

    def moeda_curta(valor):
        valor = float(valor or 0)
        if abs(valor) >= 1_000_000:
            texto = f"R$ {valor / 1_000_000:.2f} mi"
        elif abs(valor) >= 1_000:
            texto = f"R$ {valor / 1_000:.0f} mil"
        else:
            return formatar_moeda_brl(valor)
        return texto.replace(".", ",")

    resumo["Texto global"] = resumo["Valor Global"].map(moeda_curta)
    resumo["Texto desembolsado"] = resumo.apply(
        lambda linha: (
            f"{moeda_curta(linha['Valor Desembolsado'])} · "
            f"{formatar_percentual_brl(linha['Percentual desembolsado'])}"
        ),
        axis=1,
    )
    resumo["Hover global"] = resumo["Valor Global"].map(formatar_moeda_brl)
    resumo["Hover desembolsado"] = resumo["Valor Desembolsado"].map(
        formatar_moeda_brl
    )
    resumo["Hover restante"] = resumo["Valor a Desembolsar"].map(
        formatar_moeda_brl
    )
    resumo["Hover percentual"] = resumo["Percentual desembolsado"].map(
        formatar_percentual_brl
    )
    dados_hover = resumo[
        [
            "Hover global",
            "Hover desembolsado",
            "Hover restante",
            "Hover percentual",
        ]
    ].to_numpy()
    hover_completo = (
        "<b>%{y}</b><br>"
        "Valor global: %{customdata[0]}<br>"
        "Já desembolsado: %{customdata[1]}<br>"
        "A desembolsar: %{customdata[2]}<br>"
        "Percentual repassado: %{customdata[3]}"
        "<extra></extra>"
    )

    if modo == "percentual":
        eixo_total = [100.0] * len(resumo)
        eixo_repassado = resumo["Percentual visual"] * 100
        texto_total = resumo["Texto global"].map(
            lambda valor: f"Total: {valor}"
        )
        texto_repassado = resumo.apply(
            lambda linha: (
                "Sem repasse"
                if linha["Valor Desembolsado"] == 0
                else (
                    f"{formatar_percentual_brl(linha['Percentual desembolsado'])} pago"
                    f" · {moeda_curta(linha['Valor Desembolsado'])}"
                )
            ),
            axis=1,
        )
        nome_total = "Valor global (100%)"
        titulo_eixo = "Percentual já pago"
        configuracao_eixo = {
            "range": [0, 118],
            "ticksuffix": "%",
            "dtick": 20,
        }
    else:
        eixo_total = resumo["Valor global em milhões"]
        eixo_repassado = resumo["Valor desembolsado em milhões"]
        texto_total = resumo["Texto global"].map(
            lambda valor: f"Total: {valor}"
        )
        texto_repassado = resumo["Texto desembolsado"]
        nome_total = "Valor global / total"
        titulo_eixo = "Valores (R$ milhões)"
        configuracao_eixo = {"rangemode": "tozero"}

    figura = go.Figure()
    figura.add_trace(
        go.Bar(
            name=nome_total,
            x=eixo_total,
            y=resumo["Convenente / OSC"],
            orientation="h",
            width=0.72,
            marker={
                "color": COR_CIDADANIA_AZUL_CLARO,
                "line": {"color": COR_CIDADANIA_AZUL, "width": 1.4},
            },
            text=texto_total,
            textposition="outside",
            textfont={
                "color": "#071D41",
                "size": 15,
                "family": "Arial, sans-serif",
            },
            cliponaxis=False,
            customdata=dados_hover,
            hovertemplate=hover_completo,
        )
    )
    figura.add_trace(
        go.Bar(
            name="Já desembolsado / repassado",
            x=eixo_repassado,
            y=resumo["Convenente / OSC"],
            orientation="h",
            width=0.72,
            marker={
                "color": COR_CIDADANIA_VERDE,
                "line": {"color": COR_CIDADANIA_VERDE_ESCURO, "width": 0.8},
            },
            text=texto_repassado,
            textposition="auto",
            insidetextanchor="middle",
            textfont={
                "size": 15,
                "family": "Arial, sans-serif",
            },
            cliponaxis=False,
            customdata=dados_hover,
            hovertemplate=hover_completo,
        )
    )
    figura.update_layout(
        template="plotly_white",
        autosize=True,
        barmode="overlay",
        barcornerradius=14,
        bargap=0.18,
        xaxis_title=titulo_eixo,
        yaxis_title=None,
        hovermode="closest",
        transition={"duration": 650, "easing": "cubic-in-out"},
        uirevision=f"grafico-transferencias-{modo}",
        legend={
            "orientation": "h",
            "yanchor": "bottom",
            "y": 1.01,
            "xanchor": "left",
            "x": 0,
            "font": {"size": 16},
        },
        legend_title_text="",
        margin={"l": 50, "r": 275, "t": 85, "b": 75},
        height=max(1050, 180 + len(resumo) * 58),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font={"family": "Arial, sans-serif", "color": "#071D41"},
        hoverlabel={
            "bgcolor": "#FFFFFF",
            "bordercolor": "#1351B4",
            "font": {"color": "#071D41", "size": 14},
        },
    )
    figura.update_yaxes(
        automargin=True,
        tickfont={"size": 16, "color": "#071D41"},
        fixedrange=False,
    )
    figura.update_xaxes(
        showgrid=True,
        gridcolor="#E3EAF3",
        zeroline=True,
        zerolinecolor="#A7B7CC",
        tickfont={"size": 13},
        fixedrange=False,
        **configuracao_eixo,
    )
    return figura


